    import time

    LANGUAGE_WRAPPER = 'Consider the sequence of positive real numbers {a_n} with initial values a_1 = {a1} and a_2 = {a2}, which satisfies for all n ≥ 1 the nonlinear rational recurrence\n\n8\\left(\\frac{{p_coef} a_{n+2} + {q_coef}}{{s_den}}\\right)^4 = 3 + 4\\left(\\frac{{p_coef} a_{n+1} + {q_coef}}{{s_den}}\\right) + \\left(\\frac{{p_coef} a_n + {q_coef}}{{s_den}}\\right).\n\nFind a closed-form expression for a_n in terms of n. After solving, please output your final answer in the format:\n### The final answer is: \\boxed{<your formula in n>}\nYour final answer must be a formula containing n and may use standard functions such as \\cosh and \\operatorname{arcosh}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters via a conjugation of the seed recurrence by a Möbius transform b = (p*a + q)/s, with r=0 for simplicity.
# Choose k so that b1 = 2k^2 - 1 and b2 = k satisfy the seed relation b2^2 = (1 + b1)/2 exactly.
k = rng.randint(2, 8)
b1 = 2*k*k - 1
b2 = k
# Choose s_den
s_den = rng.randint(2, 9)
# We will select p_coef as a nontrivial divisor of s_den*(b1 - b2) so that both a1 and a2 can be made integers simultaneously.
delta = s_den * (b1 - b2)  # positive integer
# Compute divisors of delta greater than 1
divs = []
for d in range(2, delta + 1):
    if delta % d == 0:
        divs.append(d)
# If no divisors (shouldn't happen for delta>=2), retry
if not divs:
    # very rare fallback: set p_coef = 2 and bump s_den
    p_coef = 2
else:
    p_coef = rng.choice(divs)
# M = s*(b1 - b2)/p
M = (s_den * (b1 - b2)) // p_coef
# Choose a1 > M to keep a2 positive
a1 = M + rng.randint(2, 15)
# Compute q initially so that b1 = (p*a1 + q)/s holds
q_coef = s_den * b1 - p_coef * a1
# Ensure positivity of the entire sequence limit: need s - q > 0 so that limit a_infty = (s - q)/p is positive.
if q_coef >= s_den:
    # Increase a1 to reduce q until q < s
    needed = (q_coef - (s_den - 1) + p_coef - 1) // p_coef  # ceiling division
    a1 += max(needed, 1)
    q_coef = s_den * b1 - p_coef * a1
# Now compute a2 = a1 - M so that (p*a2 + q)/s = b2
a2 = a1 - M
# Final sanity checks: positivity and integrality
if a2 <= 0:
    # retry by increasing a1 further
    bump = rng.randint(1, 10)
    a1 += bump
    q_coef = s_den * b1 - p_coef * a1
    a2 = a1 - M
    if q_coef >= s_den:
        need2 = (q_coef - (s_den - 1) + p_coef - 1) // p_coef
        a1 += max(need2, 1)
        q_coef = s_den * b1 - p_coef * a1
        a2 = a1 - M
# Return assignment
return {'p_coef': p_coef, 'q_coef': q_coef, 's_den': s_den, 'a1': a1, 'a2': a2}

    def verifier(assign):
# Validate domain and produce the correct closed-form answer.
try:
    p = int(assign['p_coef'])
    q = int(assign['q_coef'])
    s = int(assign['s_den'])
    a1 = int(assign['a1'])
    a2 = int(assign['a2'])
except Exception:
    # invalid types
    return (False, None)
# Basic domain checks
if p <= 0 or s <= 0:
    # invalid transform
    return (False, None)
# Compute b1 and b2 from the transform
b1_num = p * a1 + q
b2_num = p * a2 + q
# Denominator is s
# Ensure exact divisibility to avoid floating issues
if b1_num % s != 0 or b2_num % s != 0:
    # We require exact mapping to integer b1, b2
    return (False, None)
b1 = b1_num // s
b2 = b2_num // s
# Check the seed relation for k via b1 = 2k^2 - 1 and b2 = k (deduce k from b2)
# This ensures the disguised recurrence is consistent and nontrivial.
if b1 != 2 * (b2 ** 2) - 1:
    # The mapping must match the half-angle identity exactly
    return (False, None)
# Enforce positivity of the limit term
if s - q <= 0:
    return (False, None)
# Build the final answer string using LaTeX, in terms of n only
# a_n = (s * cosh(arcosh(b1)/2^{n-1}) - q) / p
answer = f"### The final answer is: \\boxed{{\\frac{{{s}\\cosh\\!\left(\\frac{{\\operatorname{{arcosh}}\\,{b1}}}{{2^{{n-1}}}}\right) - {q}}}{{{p}}}}}"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

